        server={BASE_SERVER_ENABLED}
        connStatus={undefined}
        onUninstalled={() => {}}
      />
    );

    await act(async () => {
      fireEvent.click(screen.getByRole('button', { name: /disable/i }));
    });

    await waitFor(() => expect(screen.getByText('Server unavailable')).toBeInTheDocument());
  });
});

