// A `t` that resolves against the real English bundle, so these tests also prove
// the three new `mcp.connectAuth.authError.*` keys actually exist in en.ts.
const tEn = (key: string): string => (en as Record<string, string>)[key] ?? key;

describe('authHintMessageKey (#4289)', () => {
  it('maps each core auth_hint code to its i18n key', () => {
    expect(authHintMessageKey('oauth_required')).toBe('mcp.connectAuth.authError.oauthRequired');
    expect(authHintMessageKey('token_rejected')).toBe('mcp.connectAuth.authError.tokenRejected');
    expect(authHintMessageKey('credential_required')).toBe(
      'mcp.connectAuth.authError.credentialRequired'
    );
  });

  it('returns null for an unknown or absent code', () => {
    expect(authHintMessageKey('something_else')).toBeNull();
    expect(authHintMessageKey(undefined)).toBeNull();
  });

  it('every mapped key resolves to non-placeholder English copy', () => {
    for (const code of ['oauth_required', 'token_rejected', 'credential_required']) {
      const key = authHintMessageKey(code);
      expect(key).not.toBeNull();
      const copy = tEn(key as string);
      expect(copy).not.toBe(key); // resolved, not echoed back
      expect(copy.length).toBeGreaterThan(0);
    }
  });
});

describe('reconnectErrorMessage (#4289)', () => {
  it('returns null when the reconnect actually connected', () => {
    expect(reconnectErrorMessage({ status: 'connected' }, tEn)).toBeNull();
  });

  it('OAuth-only 401 → "use Sign in" copy, never the raw message', () => {
    const msg = reconnectErrorMessage({ status: 'unauthorized', auth_hint: 'oauth_required' }, tEn);
    expect(msg).toBe(tEn('mcp.connectAuth.authError.oauthRequired'));
  });

  it('rejected static token 401 → token-rejected copy', () => {
    const msg = reconnectErrorMessage({ status: 'unauthorized', auth_hint: 'token_rejected' }, tEn);
    expect(msg).toBe(tEn('mcp.connectAuth.authError.tokenRejected'));
  });

  it('401 with no/unknown hint falls back to generic reconnect copy', () => {
    // Missing hint…
    expect(reconnectErrorMessage({ status: 'unauthorized' }, tEn)).toBe(
      tEn('mcp.connectAuth.reconnectFailed')
    );
    // …and an unrecognized code (forward-compat with a future core reason).
    expect(
      reconnectErrorMessage({ status: 'unauthorized', auth_hint: 'brand_new_reason' }, tEn)
    ).toBe(tEn('mcp.connectAuth.reconnectFailed'));
  });

  it('a generic (non-401) failure surfaces its own message', () => {
    expect(reconnectErrorMessage({ status: 'disconnected', error: 'timed out' }, tEn)).toBe(
      'timed out'
    );
  });

  it('a non-401 failure with no message falls back to generic copy', () => {
    expect(reconnectErrorMessage({ status: 'disconnected' }, tEn)).toBe(
      tEn('mcp.connectAuth.reconnectFailed')
    );
  });
});

use axum::body::to_bytes;
use axum::extract::Query;
use axum::http::{header, StatusCode};
use axum::response::IntoResponse;

use super::{oauth_mcp_callback_handler, OAuthMcpCallbackQuery};

#[tokio::test]
async fn oauth_callback_reports_provider_denial_as_html_without_attempting_exchange() {
    let response = oauth_mcp_callback_handler(Query(OAuthMcpCallbackQuery {
        code: Some("unused-code".into()),
        state: Some("unused-state".into()),
        error: Some("access_denied".into()),
        error_description: Some("user declined".into()),
    }))
    .await
    .into_response();

    assert_eq!(response.status(), StatusCode::BAD_REQUEST);
    assert_eq!(
        response.headers()[header::CONTENT_TYPE],
        "text/html; charset=utf-8"
    );
    let body = to_bytes(response.into_body(), usize::MAX).await.unwrap();
    let html = String::from_utf8_lossy(&body);
    assert!(html.contains("access_denied"));
    assert!(html.contains("user declined"));
}

#[tokio::test]
async fn oauth_callback_requires_nonblank_code_and_state() {
    for (code, state) in [
        (None, Some("state")),
        (Some("code"), None),
        (Some("  "), Some("state")),
        (Some("code"), Some("  ")),
    ] {
        let response = oauth_mcp_callback_handler(Query(OAuthMcpCallbackQuery {
            code: code.map(str::to_string),
            state: state.map(str::to_string),
            error: None,
            error_description: None,
        }))
        .await
        .into_response();
        assert_eq!(response.status(), StatusCode::BAD_REQUEST);
        let body = to_bytes(response.into_body(), usize::MAX).await.unwrap();
        assert!(String::from_utf8_lossy(&body).contains("Missing authorization code or state"));
    }
}

//! Journal projection of `AgentEvent::Compacted`.

use tinyagents_harness::events::AgentEvent;

/// Logs a context compaction at info with its token savings and the
/// summarizer call's latency and usage (grep `context compacted`).
///
/// A compaction rewrites what the model sees and spends a summarizer call
/// outside the turn's own model calls, so it is worth seeing at the default
/// log level, with that call's cost.
pub(super) fn log_compacted(event: &AgentEvent) {
    let AgentEvent::Compacted {
        reason,
        tokens_before,
        tokens_after,
        usage,
        latency_ms,
    } = event
    else {
        return;
    };
    tracing::info!(
        reason = reason.as_str(),
        tokens_before,
        tokens_after,
        saved_tokens = tokens_before.saturating_sub(*tokens_after),
        latency_ms = ?latency_ms,
        summarizer_input_tokens = ?usage.map(|u| u.input_tokens),
        summarizer_output_tokens = ?usage.map(|u| u.output_tokens),
        summarizer_cached_tokens = ?usage.map(|u| u.cache_read_tokens),
        "[tinyagents] context compacted"
    );
}

use super::*;
use crate::security::policy::AutonomyLevel;
use serde_json::json;
use tinytools::ToolResult;

/// Minimal registered tool. `execute` is unreachable: this adapter answers
/// questions about tools, it never runs them.
struct FakeTool {
    name: &'static str,
    permission: PermissionLevel,
    external: bool,
}

#[async_trait]
impl Tool for FakeTool {
    fn name(&self) -> &str {
        self.name
    }
    fn description(&self) -> &str {
        "test tool"
    }
    fn parameters_schema(&self) -> serde_json::Value {
        json!({ "type": "object" })
    }
    fn permission_level(&self) -> PermissionLevel {
        self.permission
    }
    fn external_effect(&self) -> bool {
        self.external
    }
    async fn execute(&self, _args: serde_json::Value) -> anyhow::Result<ToolResult> {
        unreachable!("the security gate never executes a tool")
    }
}

fn tool(name: &'static str, permission: PermissionLevel, external: bool) -> Box<dyn Tool> {
    Box::new(FakeTool {
        name,
        permission,
        external,
    })
}

fn registry() -> Vec<Arc<Vec<Box<dyn Tool>>>> {
    vec![Arc::new(vec![
        tool("read_file", PermissionLevel::ReadOnly, false),
        tool("write_file", PermissionLevel::Write, false),
        tool(SHELL_TOOL, PermissionLevel::Execute, false),
    ])]
}

fn policy(autonomy: AutonomyLevel) -> Arc<SecurityPolicy> {
    Arc::new(SecurityPolicy {
        autonomy,
        ..SecurityPolicy::default()
    })
}

fn gate(autonomy: AutonomyLevel) -> OpenHumanSecurityGate {
    OpenHumanSecurityGate::new(policy(autonomy), registry())
}

fn req(tool_name: &str, args: serde_json::Value) -> ToolCallRequest {
    ToolCallRequest::new(tool_name, args, "lead")
}

#[tokio::test]
async fn there_is_no_audit_id_to_drain_when_nothing_was_prompted() {
    // No approval gate is installed in tests, so nothing parks and nothing
    // is stashed. The point of the assertion is that `take_audit_request_id`
    // is a drain, not a source: a caller can never mistake "not prompted"
    // for "there is a row to close", which is what would push it into
    // issuing a second `intercept_audited` and raising a duplicate card.
    let gate = gate(AutonomyLevel::Full);
    let _ = gate
        .authorize_tool(&req("read_file", json!({ "path": "notes.md" })))
        .await
        .expect("authorize");

    assert_eq!(gate.take_audit_request_id("any-call-id"), None);
}

#[test]
fn draining_an_audit_id_yields_it_exactly_once() {
    // An id is valid for exactly one `record_execution`; handing the same
    // one out twice would write two terminal rows for a single approval.
    let gate = gate(AutonomyLevel::Full);
    gate.pending_audit
        .lock()
        .expect("uncontended")
        .insert("call-1".to_string(), "request-9".to_string());

    assert_eq!(
        gate.take_audit_request_id("call-1"),
        Some("request-9".to_string())
    );
    assert_eq!(gate.take_audit_request_id("call-1"), None);
}

